 if typ not in c['examinationAngles']:c['examinationAngles'].append(typ)
 citations=[{'slideId':f'lectures-p{p:04d}','sourceId':'lectures','sourceSha256':SHA,'physicalPage':p,'kind':'figure' if typ=='diagram' else 'equation' if typ in ('numerical','derivation') else 'statement','locator':f'Lecture 10, physical PDF page {p}, printed slide {p-325}: displayed derivation, text and associated figure','evidenceText':(R/f'sources/text/lectures/page-{p:04d}.txt').read_text().strip(),'role':'conflict' if conflict else 'premise' if typ in ('numerical','derivation','scenario') else 'explicit','region':None} for p in pages]
 ids=[f'choice-{i+1}' for i in range(4)];opts=[{'id':ids[i],'text':o} for i,o in enumerate(options)];shift=len(qs)%4;opts=opts[shift:]+opts[:shift]
 q={'id':qid,'version':1,'status':'draft','authorId':AUTHOR,'stem':stem,'selectionMode':'multi' if len(correct)>1 else 'single','type':typ,'difficulty':diff,'cognitiveSkill':'numerical' if typ=='numerical' else 'application' if typ in ('scenario','diagram') else 'recall' if typ in ('definition','match') else 'synthesis' if typ=='derivation' else 'conceptual','week':2,'lectureId':'L10','topic':'Static forces and velocity propagation','subtopic':title,'tags':[key],'conceptIds':[cid],'assumptions':assumptions or [],'options':opts,'correctOptionIds':[ids[i] for i in correct],'citations':citations,'solution':{'justification':why,'optionExplanations':dict(zip(ids,expl)),'steps':steps or [],'formulas':formulas or [],'simpleExplanation':why,'memoryAid':None,'misconceptions':[expl[i] for i in range(4) if i not in correct],'examTraps':[],'prerequisiteConceptIds':[]},'origin':'generated','reviewIds':[]}
