jac=form('J³=[[L1 sinθ2,0],[L2+L1 cosθ2,L2]]; J⁰=R(θ1+θ2)J³',{'J³,J⁰':'planar position Jacobians in tip and base coordinates','R':'2×2 planar rotation','L1,L2':'positive link lengths','θ1,θ2':'joint angles'},{'L1,L2':'m','θ1,θ2':'rad','J³,J⁰':'m/rad'},['Same tip point; planar x/y task, not the full spatial twist.'])
