add(329,'planar-transforms','Three transforms for a two-joint arm','Which interpretation matches the three displayed transforms?', ['T01 rotates by θ1; T12 translates L1 along x1 and rotates by θ2; T23 translates L2 with no relative rotation','T01 translates L1; T12 rotates by θ1+θ2; T23 rotates by θ2','T01 and T12 are translations only; T23 contains both joint rotations','T01 rotates by θ1; T12 translates along y1; T23 rotates through a third actuated angle'],0,'The first transform has zero translation, the second has x1 offset L1, and the third has identity rotation with x2 offset L2.', ['All three blocks match the source.','This relocates the first translation and double-counts θ2.','The first two rotations are explicitly non-identity.','The offsets are along x, and frame3 is not an additional actuated joint.'],typ='match')
add(329,'diagram-frames','Interpreting the frame diagram','In the arm diagram, which relation between frames2 and3 agrees with T23?', ['Their axes are parallel, while their origins are separated along the second link','Their origins coincide but their axes differ by θ2','Their origins coincide and their axes differ by θ1','Their axes differ by90° because the second link is bent relative to the first'],0,'The frame3 origin is at the tip and frame2 at the elbow; identity rotation in T23 means aligned axes.', ['This matches the origin offset and identity rotation.','θ2 is relative to frame1, not frame3 to frame2.','The diagram and translation column show distinct origins.','The elbow bend is already represented by T12.'],typ='diagram',diff='easy')
add(329,'mdh-entry','Checking the general transform entry','Using Rx(α_(i−1))Rz(θ_i), what belongs in rotation row3,column2, where the printed general matrix shows sinα_i?', ['sinα_(i−1) cosθ_i','sinα_i','cosα_(i−1) sinθ_i','−sinα_(i−1)'],0,'Multiplying row3 of Rx by column2 of Rz gives sinα_(i−1)cosθ_i; the printed entry omits both the proper index and cosθ_i factor.', ['This is the direct product entry.','This repeats the inconsistent printed expression.','This mixes the row2/row3 factors.','This is related to row2,column3, not row3,column2.'],typ='derivation',steps=['Row3 of Rx is [0,sinα,cosα].','Column2 of Rz is [−sinθ,cosθ,0].','Their dot product is sinα cosθ.'],formulas=[form('Rx(α)Rz(θ) row3,column2 = sinα cosθ',{'α':'preceding-link twist α_(i−1)','θ':'joint angle θ_i'},{'α,θ':'rad','rotation entry':'dimensionless'})],conflict='The general modified-DH matrix on physical page329 prints sinα_i at row3,column2.')
add(330,'angular-sum','Angular propagation on parallel axes','Why is the second link’s angular velocity [0,0,q1dot+q2dot] in frame2?', ['The first link’s z angular velocity is unchanged by a z rotation, then the second joint adds its z rate','The second joint replaces the inherited angular velocity with its own rate','Linear velocity at the first joint is added directly to the second angular rate','Both rates must be subtracted because frame2 is rotated relative to frame1'],0,'A rotation about z leaves a z-directed vector unchanged; the revolute relative rate is then added.', ['This is the displayed recursion.','Inherited and relative angular motion both contribute.','Linear and angular rates have different physical roles.','Frame rotation does not imply subtracting parallel-axis rates.'],typ='conceptual')
add(330,'fixed-origin','Rotation without origin translation','The frame1 origin is fixed, while q1dot≠0; which pair is consistent?', ['v1=0 and ω1=[0,0,q1dot]','v1=[0,0,q1dot] and ω1=0','v1=0 and ω1=0','v1=L1q1dot along x1 and ω1=[0,0,q1dot]'],0,'An origin on the fixed joint axis can have zero linear velocity while its attached frame rotates.', ['Fixed position does not prohibit changing orientation.','This substitutes an angular rate for linear velocity.','The nonzero joint rate makes orientation change.','The L1 offset belongs to the next joint origin.'],typ='scenario',diff='easy')
add(331,'elbow-velocity','Velocity caused by the first-link offset','For L1=2 m, θ2=30° and q1dot=1 rad/s, what is v2 expressed in frame2?', ['(1,√3,0) m/s','(−1,√3,0) m/s','(√3,1,0) m/s','(0,2,0) m/s'],0,'The source obtains v2=[L1q1dot sinθ2,L1q1dot cosθ2,0], giving (1,√3,0).', ['This applies both the offset cross product and frame rotation.','This uses the opposite rotation sign.','This interchanges sine and cosine.','This is the intermediate vector before expressing it in frame2.'],typ='numerical',steps=['ω1×p12=(0,2,0) m/s in frame1.','Rotate by −30° into frame2.','The resulting components are (1,√3,0) m/s.'],formulas=[form('v2²=[L1 q1dot sinθ2,L1 q1dot cosθ2,0]',{'v2²':'frame2-origin velocity expressed in frame2','L1':'first-link length','q1dot':'first joint rate','θ2':'relative angle'},{'v2²':'m/s','L1':'m','q1dot':'rad/s','θ2':'rad'})])
add(331,'frame-consistency','Consistent frames in velocity propagation','The first general line prints a leading frame i on the output, but multiplies by R_(i+1,i); what expression frame follows from the multiplication and worked example?', ['Frame i+1','Frame i','The inertial frame automatically','A mixture of frame i for x and frame i+1 for y'],0,'The bracket is expressed in frame i; premultiplying by the rotation into i+1 changes all components to frame i+1, as the worked v2² shows.', ['This is consistent with the rotation direction.','This retains the inconsistent leading label.','A relative rotation does not automatically express a vector in the base.','A vector must use one consistent coordinate basis.'],typ='derivation',conflict='The first recursion on physical page331 has a leading output-frame superscript i despite the rotation into i+1; its worked example correctly uses frame2.')
add(332,'same-link-velocities','Two points on one rigid link','Frames2 and3 are fixed on the same link with aligned axes; which statement is correct?', ['Their angular velocities match, but their linear velocities can differ by ω×p23','Both linear and angular velocities must be identical at any two origins','Their linear velocities match, but angular velocities differ by L2','Their angular velocities differ whenever their origins do not coincide'],0,'Rigid-body angular velocity is common, whereas an offset point acquires the tangential velocity ω×p.', ['This is the propagation shown.','Distinct rigid-body points can have different linear velocities.','A length is not an angular-velocity difference.','Origin translation does not create a relative rigid-body rotation.'],typ='conceptual')
add(332,'tip-velocity','Combining inherited and offset velocities','For L1=2 m, L2=1 m, θ2=90°, q1dot=1 rad/s and q2dot=−0.5 rad/s, what is v3 in frame3?', ['(2,0.5,0) m/s','(2,−0.5,0) m/s','(0,2.5,0) m/s','(2,1.5,0) m/s'],0,'The x component is2; the y component is0+(1−0.5)×1=0.5.', ['Both inherited and relative rates enter the second-link term.','This omits the inherited q1dot contribution to angular velocity.','This treats sin90° and cos90° as interchangeable.','This reverses the sign of q2dot.'],typ='numerical',steps=['v3,x=L1 sinθ2 q1dot=2.','v3,y=L1 cosθ2 q1dot+L2(q1dot+q2dot)=0.5.','Planar v3,z=0.'],formulas=[kin])
